{"nbformat":4,"nbformat_minor":0,"metadata":{"colab":{"provenance":[],"authorship_tag":"ABX9TyMkuYtH9GmVZ1uwTntKRg3P"},"kernelspec":{"name":"python3","display_name":"Python 3"},"language_info":{"name":"python"}},"cells":[{"cell_type":"code","execution_count":null,"metadata":{"id":"NRJQ-7vN3TXW"},"outputs":[],"source":["from flask import Flask, request, jsonify, render_template\n","from langchain_community.document_loaders import UnstructuredURLLoader\n","from langchain.text_splitter import RecursiveCharacterTextSplitter\n","from langchain.embeddings import HuggingFaceEmbeddings\n","from langchain_chroma import Chroma\n","from langchain_core.runnables import RunnablePassthrough\n","from langchain.prompts import PromptTemplate\n","from langchain_huggingface import HuggingFacePipeline\n","from langchain_core.output_parsers import StrOutputParser\n","from transformers import pipeline\n","\n","# Initialisation\n","app = Flask(__name__)\n","\n","# Préparation des documents\n","urls = [\n","    \"https://agricultureduvivant.org/les-types-dagriculture/\",\n","    \"https://agricultureduvivant.org/lagroecologie/la-couverture-vegetale-un-incontournable-pour-un-sol-vivant/\",\n","    \"https://agricultureduvivant.org/lagroecologie/lagroecologie-remettre-lagronomie-au-coeur-de-la-transition/\",\n","    \"https://agricultureduvivant.org/lagroecologie/tous-ensemble-pour-reussir-la-transition-agroecologique/\",\n","    \"https://agricultureduvivant.org/les-types-dagriculture/lagriculture-regeneratrice/\",\n","    \"https://isra.sn/enjeux-et-defis/\"\n","]\n","docs = RecursiveCharacterTextSplitter(chunk_size=1000).split_documents(UnstructuredURLLoader(urls).load())\n","embeddings = HuggingFaceEmbeddings()\n","vectorstore = Chroma.from_documents(docs, embeddings)\n","retriever = vectorstore.as_retriever(search_type=\"similarity\", search_kwargs={\"k\": 2})\n","\n","# Modèle plus léger (adapté CPU)\n","text_gen = pipeline(\"text2text-generation\", model=\"google/flan-t5-base\", max_new_tokens=300)\n","llm = HuggingFacePipeline(pipeline=text_gen)\n","\n","prompt_template = \"\"\"\n","Réponds à la question suivante en utilisant le contexte :\n","\n","Contexte : {context}\n","\n","Question : {question}\n","\n","Réponse :\n","\"\"\"\n","prompt = PromptTemplate(template=prompt_template, input_variables=[\"context\", \"question\"])\n","llm_chain = prompt | llm | StrOutputParser()\n","rag_chain = {\"context\": retriever, \"question\": RunnablePassthrough()} | llm_chain\n","\n","@app.route('/', methods=[\"GET\", \"POST\"])\n","def index():\n","    if request.method == \"POST\":\n","        question = request.form[\"question\"]\n","        try:\n","            answer = rag_chain.invoke(question).strip()\n","        except Exception as e:\n","            answer = f\"Erreur : {str(e)}\"\n","        return render_template(\"index.html\", question=question, answer=answer)\n","    return render_template(\"index.html\")\n","\n","if __name__ == \"__main__\":\n","    app.run(debug=True)\n"]}]}